// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue, getResponseValue } from '@skyramp/skyramp';
import {
    createOwner,
    createOwnerPet,
    updatePet,
    deletePet,
    deleteOwner
} from './skyrampUtils';

// URL for test requests
const URL_localhost = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:9966");

// This step's request omits the nickname key altogether, which no dataOverride on the
// shared createOwnerPet helper can express, so it stays local under its own name.
async function createOwnerPetWithoutNickname(
    client: SkyrampClient,
    ownerId: unknown,
    name = "NoNick",
    birthDate = "2020-01-01",
    expectedStatus = 201
) {
    // Request Body
    const petsPost1RequestBody: string = `{
        "birthDate": "2020-01-01",
        "name": "NoNick",
        "type": {
            "id": 1,
            "name": "cat"
        }
    }`;

    // Execute Request
    const petsPost1Response = await client.sendRequest({
        url: URL_localhost,
        path: "/petclinic/api/owners/{owners}/pets",
        method: "POST",
        body: petsPost1RequestBody,
        pathParams: {"owners": ownerId},
        dataOverride: {
            "birthDate": birthDate,
            "name": name
        }
    });

    // Generated Assertions
    expect(petsPost1Response.statusCode, 'status code').toBe(expectedStatus);

    return petsPost1Response;
}

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Declaration of variables
    const owners = "999999";

    const ownersPostResponse = await createOwner(
        client,
        "Nickname",
        "Bounds",
        "2 Nickname St.",
        "Madison",
        "6085550002"
    );

    expect(ownersPostResponse.statusCode, 'status code').toBe(201);
    expect(Number(getResponseValue(ownersPostResponse, "id")), 'owner id').toBeGreaterThan(0);
    expect(getResponseValue(ownersPostResponse, "firstName"), 'firstName').toBe("Nickname");
    expect(getResponseValue(ownersPostResponse, "lastName"), 'lastName').toBe("Bounds");
    expect(getResponseValue(ownersPostResponse, "telephone"), 'telephone').toBe("6085550002");

    const petsPostResponse = await createOwnerPet(
        client,
        getResponseValue(ownersPostResponse, "id"),
        "MaxNick",
        "2020-01-01",
        "123456789012345678901234567890"
    );

    expect(petsPostResponse.statusCode, 'status code').toBe(201);
    expect(Number(getResponseValue(petsPostResponse, "id")), 'pet id').toBeGreaterThan(0);
    expect(getResponseValue(petsPostResponse, "nickname"), 'a 30 character nickname is stored in full').toBe("123456789012345678901234567890");
    expect(getResponseValue(petsPostResponse, "name"), 'name').toBe("MaxNick");

    const petsPost1Response = await createOwnerPetWithoutNickname(
        client,
        getResponseValue(ownersPostResponse, "id"),
        "NoNick",
        "2020-01-01"
    );

    expect(petsPost1Response.statusCode, 'status code').toBe(201);
    expect(Number(getResponseValue(petsPost1Response, "id")), 'pet id').toBeGreaterThan(0);
    expect(getResponseValue(petsPost1Response, "name"), 'name').toBe("NoNick");
    expect(getResponseValue(petsPost1Response, "nickname") ?? null, 'an omitted nickname stays unset').toBeNull();

    const petsPost2Response = await createOwnerPet(
        client,
        getResponseValue(ownersPostResponse, "id"),
        "EmptyNick",
        "2020-01-01",
        "",
        400
    );

    expect(petsPost2Response.statusCode, 'status code').toBe(400);
    expect(getResponseValue(petsPost2Response, "detail"), 'detail').toBe("The request contains invalid or missing parameters");
    expect(getResponseValue(petsPost2Response, "title"), 'title').toBe("MethodArgumentNotValidException");
    expect(getResponseValue(petsPost2Response, "schemaValidationErrors.0.field"), 'rejected field').toBe("nickname");
    expect(getResponseValue(petsPost2Response, "schemaValidationErrors.0.defaultMessage"), 'rejection reason').toBe("size must be between 1 and 30");
    expect(getResponseValue(petsPost2Response, "schemaValidationErrors.0.rejectedValue"), 'rejected value').toBe("");
    expect(getResponseValue(petsPost2Response, "schemaValidationErrors.1") ?? null, 'only the nickname is rejected').toBeNull();
    expect(getResponseValue(petsPost2Response, "id") ?? null, 'no pet was created').toBeNull();

    const petsPost3Response = await createOwnerPet(
        client,
        getResponseValue(ownersPostResponse, "id"),
        "LongNick",
        "2020-01-01",
        "1234567890123456789012345678901",
        400
    );

    expect(petsPost3Response.statusCode, 'status code').toBe(400);
    expect(getResponseValue(petsPost3Response, "detail"), 'detail').toBe("The request contains invalid or missing parameters");
    expect(getResponseValue(petsPost3Response, "title"), 'title').toBe("MethodArgumentNotValidException");
    expect(getResponseValue(petsPost3Response, "schemaValidationErrors.0.field"), 'rejected field').toBe("nickname");
    expect(getResponseValue(petsPost3Response, "schemaValidationErrors.0.defaultMessage"), 'rejection reason').toBe("size must be between 1 and 30");
    expect(getResponseValue(petsPost3Response, "schemaValidationErrors.0.rejectedValue"), 'rejected value').toBe("1234567890123456789012345678901");
    expect(getResponseValue(petsPost3Response, "schemaValidationErrors.1") ?? null, 'only the nickname is rejected').toBeNull();
    expect(getResponseValue(petsPost3Response, "id") ?? null, 'no pet was created').toBeNull();

    const petsPost4Response = await createOwnerPet(
        client,
        owners,
        "OrphanNick",
        "2020-01-01",
        "Buddy",
        404
    );

    expect(petsPost4Response.statusCode, 'status code').toBe(404);
    expect(getResponseValue(petsPost4Response, "id") ?? null, 'no pet was created for an owner that does not exist').toBeNull();

    const petsPetsPutResponse = await updatePet(
        client,
        owners,
        getResponseValue(petsPostResponse, "ownerId"),
        "OrphanNick",
        "2020-01-01",
        1,
        "cat",
        "Buddy",
        404
    );

    expect(petsPetsPutResponse.statusCode, 'status code').toBe(404);
    expect(getResponseValue(petsPetsPutResponse, "nickname") ?? null, 'no pet was updated for a pet that does not exist').toBeNull();

    const petsPetsDeleteResponse = await deletePet(client, getResponseValue(petsPostResponse, "id"));

    const petsPetsDelete1Response = await deletePet(client, getResponseValue(petsPost1Response, "id"));

    expect(petsPetsDelete1Response.statusCode, 'status code').toBe(204);

    const ownersOwnersDeleteResponse = await deleteOwner(client, getResponseValue(ownersPostResponse, "id"));
});
